package ai.eva.android.probe;
import android.app.*;import android.os.*;import android.content.*;import java.io.*;import java.nio.file.*;import java.util.concurrent.*;
/** Device checks use actual bridge and local files; fixtures are removed afterwards. */
public class PageCheck extends Instrumentation {
 ShellActivity shell;FilesActivity local;BrowserActivity browserPage;TerminalActivity terminalPage;
 String js(String script)throws Exception{CountDownLatch latch=new CountDownLatch(1);String[] answer={null};runOnMainSync(()->shell.web.evaluateJavascript(script,v->{answer[0]=v;latch.countDown();}));if(!latch.await(10,TimeUnit.SECONDS))throw new Exception("JavaScript timeout");return answer[0];}
 String browserJs(String script)throws Exception{CountDownLatch latch=new CountDownLatch(1);String[] answer={null};runOnMainSync(()->browserPage.browser.evaluateJavascript(script,v->{answer[0]=v;latch.countDown();}));if(!latch.await(10,TimeUnit.SECONDS))throw new Exception("Browser JavaScript timeout");return answer[0];}
 void browserFixture()throws Exception{runOnMainSync(()->browserPage.browser.loadDataWithBaseURL("https://eva-layout-test.invalid/","<script>window.earlyPlatform=navigator.platform;window.earlyWidth=screen.width;window.earlyTouch=navigator.maxTouchPoints;if(navigator.userAgentData)navigator.userAgentData.getHighEntropyValues(['architecture','bitness','model','platformVersion','fullVersionList']).then(x=>window.deviceHints=x)</script><meta name='viewport' content='width=device-width,initial-scale=1'><title>布局验证</title><style>body{font:24px sans-serif;margin:32px}main{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}article{background:#eef3f8;padding:32px}@media(max-width:700px){main{grid-template-columns:1fr}}</style><h1>Eva 浏览器布局验证</h1><p>桌面模式展示四列工作区，可双指缩放。</p><main><article>项目文件</article><article>编辑器</article><article>运行记录</article><article>页面预览</article></main>","text/html","UTF-8",null));for(int n=0;n<40;n++){if(browserJs("document.title").contains("布局验证")){Thread.sleep(450);return;}Thread.sleep(100);}throw new Exception("Fixture did not load");}
 String requestHeaders()throws Exception{
  CountDownLatch latch=new CountDownLatch(1);String[] headers={null};android.webkit.WebViewClient[] original={null};
  runOnMainSync(()->{original[0]=browserPage.browser.getWebViewClient();browserPage.browser.setWebViewClient(new android.webkit.WebViewClient(){
   public android.webkit.WebResourceResponse shouldInterceptRequest(android.webkit.WebView view,android.webkit.WebResourceRequest request){if("eva-request-test.invalid".equals(request.getUrl().getHost())){headers[0]=new org.json.JSONObject(request.getRequestHeaders()).toString();latch.countDown();return new android.webkit.WebResourceResponse("text/html","UTF-8",new ByteArrayInputStream("<title>请求验证</title>".getBytes(java.nio.charset.StandardCharsets.UTF_8)));}return original[0].shouldInterceptRequest(view,request);}
  });browserPage.browser.loadUrl("https://eva-request-test.invalid/");});
  if(!latch.await(10,TimeUnit.SECONDS))throw new Exception("Request headers timeout");runOnMainSync(()->{browserPage.browser.stopLoading();browserPage.browser.setWebViewClient(original[0]);});return headers[0];
 }
 void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 void shot(String name)throws Exception{waitForIdleSync();Thread.sleep(350);Activity activity=name.startsWith("browser")?browserPage:name.equals("terminal")?terminalPage:(name.equals("files")||name.equals("preview")||name.equals("binary"))?local:shell;runOnMainSync(()->{android.view.View view=activity.getWindow().getDecorView();android.graphics.Bitmap image=android.graphics.Bitmap.createBitmap(view.getWidth(),view.getHeight(),android.graphics.Bitmap.Config.ARGB_8888);view.draw(new android.graphics.Canvas(image));try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),"page-"+name+".png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}catch(Exception e){throw new RuntimeException(e);}image.recycle();});}
 public void onCreate(Bundle args){super.onCreate(args);start();}
 public void onStart(){Bundle result=new Bundle();int code=0;File fixture=null,taskFixture=null;String saved=null;android.content.SharedPreferences prefs=getTargetContext().getSharedPreferences("eva-settings",0);String oldFolder=getTargetContext().getSharedPreferences("eva-files",0).getString("folder",""),oldUrl=getTargetContext().getSharedPreferences("eva-browser",0).getString("lastUrl",null),oldCommand=getTargetContext().getSharedPreferences("eva-terminal",0).getString("command",null);boolean hadDesktop=prefs.contains("browserDesktop"),oldDesktop=prefs.getBoolean("browserDesktop",true);int timeout=prefs.getInt("commandTimeout",120);String theme=prefs.getString("theme","light"),url=prefs.getString("browserHome","https://example.com");try{
  Intent i=new Intent(getTargetContext(),ShellActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);shell=(ShellActivity)startActivitySync(i);
  for(int n=0;n<50;n++){if("\"function\"".equals(js("typeof settingsGo")))break;Thread.sleep(100);}
  saved=getTargetContext().getSharedPreferences("eva-ui",0).getString("state","{\"chats\":[]}");
  js("data={chats:[],draft:'',active:null};route='home';render()");shot("home");js("navigate('drawer')");check("3".equals(js("document.querySelectorAll('nav[aria-label=主要功能] .row').length")),"primary navigation");shot("drawer");js("navigate('close')");
  check("true".equals(js("document.querySelector('[data-action=save]').disabled")),"empty save must be disabled");
  js("document.querySelector('#prompt').value='页面验证';navigate('save')");shot("chat");js("navigate('edit-chat')");shot("chat-edit");js("evaBack();navigate('tasks')");shot("tasks");
  taskFixture=new File(getTargetContext().getFilesDir(),"alpine/root/eva-tasks/ui-check-"+java.util.UUID.randomUUID());taskFixture.mkdirs();
  Files.write(new File(taskFixture,"state.json").toPath(),"{\"state\":\"failed\",\"argv\":[\"sh\",\"-c\",\"示例命令\"],\"exitCode\":1}".getBytes("UTF-8"));
  Files.write(new File(taskFixture,"events.jsonl").toPath(),("{\"type\":\"output\",\"stream\":\"stdout\",\"base64\":\"b2s=\"}\n{\"type\":\"output\",\"stream\":\"stderr\",\"base64\":\"ZXJyb3I=\"}\n").getBytes("UTF-8"));
  org.json.JSONObject detail=new org.json.JSONObject(shell.new Bridge().taskDetail(taskFixture.getName()));check(detail.getString("stdout").equals("ok")&&detail.getString("stderr").equals("error"),"task stream separation");check(new org.json.JSONObject(shell.new Bridge().taskDetail("../bad")).has("error"),"task path boundary");
  js("navigate('task:"+taskFixture.getName()+"')");shot("task-detail");js("evaBack()");
  for(String page:new String[]{"settings","models","permissions","execution","browser","storage","appearance","about"}){js("settingsGo('"+page+"')");shot("settings-"+page);}
  js("settingsGo('execution');settingSave('commandTimeout','60')");check(prefs.getInt("commandTimeout",0)==60,"timeout persistence");
  js("settingsGo('appearance');settingSave('theme','dark')");check(prefs.getString("theme","").equals("dark"),"theme persistence");shot("dark");
  check(js("JSON.parse(EvaHost.setSetting('browserHome','http://example.com')).error").contains("HTTPS"),"reject HTTP");
  js("EvaHost.setSetting('theme','light')");
  Intent tool=new Intent(getTargetContext(),FilesActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);local=(FilesActivity)startActivitySync(tool);
  fixture=new File(local.workspace(),"ui-check-"+java.util.UUID.randomUUID());fixture.mkdir();File text=new File(fixture,"你好.txt");Files.write(text.toPath(),"中文 UTF-8\n第二行".getBytes("UTF-8"));File binary=new File(fixture,"binary.bin");Files.write(binary.toPath(),new byte[]{0,1,2});final File directory=fixture;
  check(!local.inWorkspace(local.workspace().getParentFile()),"workspace boundary");
  runOnMainSync(()->local.showFolder(directory));shot("files");runOnMainSync(()->local.search.setText("你好"));check(local.count.getText().toString().contains("1"),"file search");runOnMainSync(()->local.search.setText("no-match"));check(local.count.getText().toString().contains("0"),"file search empty");runOnMainSync(()->local.search.setText(""));runOnMainSync(()->local.preview(text));shot("preview");runOnMainSync(()->local.onBackPressed());check(local.previewFile==null,"preview back");runOnMainSync(()->local.preview(binary));shot("binary");
  prefs.edit().remove("browserDesktop").commit();
  browserPage=(BrowserActivity)startActivitySync(new Intent(getTargetContext(),BrowserActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));check(browserPage.root.getChildCount()==6,"browser compact toolbar structure");browserFixture();check(browserPage.desktop,"desktop default");check(browserPage.metadataSupported&&browserPage.earlyScriptSupported,"required WebView features");check("\"Linux x86_64\"".equals(browserJs("earlyPlatform")),"platform before page scripts");check("1280".equals(browserJs("earlyWidth")),"screen before page scripts");check("0".equals(browserJs("earlyTouch")),"desktop input metadata");
  org.json.JSONObject hints=new org.json.JSONObject(new org.json.JSONTokener(browserJs("JSON.stringify(deviceHints)")).nextValue().toString());check(hints.getString("platform").equals("Linux")&&!hints.getBoolean("mobile")&&hints.getString("model").isEmpty()&&hints.getString("architecture").equals("x86")&&hints.getString("bitness").equals("64"),"desktop client hints");result.putString("desktopHints",hints.toString());String desktopUa=browserJs("navigator.userAgent");check(!desktopUa.contains("Android")&&!desktopUa.contains("Mobile"),"desktop UA");check(Integer.parseInt(browserJs("innerWidth"))>=1200,"desktop viewport");check("\"undefined\"".equals(browserJs("typeof EvaHost")),"no native bridge in browser");shot("browser-desktop");result.putString("requestHeaders",requestHeaders());
  runOnMainSync(()->browserPage.changeMode(false));browserFixture();check(!prefs.getBoolean("browserDesktop",true),"mobile mode persistence");check(!"\"Linux x86_64\"".equals(browserJs("earlyPlatform")),"mobile platform restored");check("true".equals(browserJs("navigator.userAgentData.mobile")),"mobile client hints restored");check(Integer.parseInt(browserJs("innerWidth"))<900,"mobile viewport");shot("browser-mobile");
  runOnMainSync(()->browserPage.changeMode(true));browserFixture();shot("browser");
  terminalPage=(TerminalActivity)startActivitySync(new Intent(getTargetContext(),TerminalActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));check(terminalPage.root.getChildCount()==3,"terminal has dedicated header and body");shot("terminal");runOnMainSync(()->terminalPage.command.setText(""));check(!terminalPage.runControl.isEnabled(),"empty command disabled");
  runOnMainSync(()->terminalPage.command.setText("draft-preservation-check"));runOnMainSync(()->terminalPage.finish());waitForIdleSync();check(getTargetContext().getSharedPreferences("eva-terminal",0).getString("command","").equals("draft-preservation-check"),"terminal draft persisted");
  check(!TerminalActivity.class.equals(FilesActivity.class)&&!FilesActivity.class.equals(BrowserActivity.class),"separate activity classes");
  result.putString("result","PASS: shell pages, empty input, settings persistence, URL rejection, files/preview/back/binary/boundary, three independent activities, terminal draft, primary navigation, desktop UA/client hints/document-start platform/1280 viewport/default/mobile restore/no bridge");code=-1;
 }catch(Throwable e){result.putString("error",e.toString());}finally{
  runOnMainSync(()->{if(terminalPage!=null)terminalPage.finish();if(browserPage!=null)browserPage.finish();if(local!=null)local.finish();});waitForIdleSync();
  getTargetContext().getSharedPreferences("eva-files",0).edit().putString("folder",oldFolder).commit();getTargetContext().getSharedPreferences("eva-browser",0).edit().putString("lastUrl",oldUrl).commit();getTargetContext().getSharedPreferences("eva-terminal",0).edit().putString("command",oldCommand).commit();
  if(hadDesktop)prefs.edit().putBoolean("browserDesktop",oldDesktop).commit();else prefs.edit().remove("browserDesktop").commit();
  prefs.edit().putInt("commandTimeout",timeout).putString("theme",theme).putString("browserHome",url).commit();
  if(saved!=null)getTargetContext().getSharedPreferences("eva-ui",0).edit().putString("state",saved).commit();
  if(taskFixture!=null){File[] files=taskFixture.listFiles();if(files!=null)for(File f:files)f.delete();taskFixture.delete();}
  if(fixture!=null){File[] files=fixture.listFiles();if(files!=null)for(File f:files)f.delete();fixture.delete();}
 }finish(code,result);}
}
